import{_ as t,o,c as a,a2 as n}from"./chunks/framework.CZo9GF0W.js";const m=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1789060268000}'),i={name:"guide/troubleshooting.md"};function s(r,e,d,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Start here: <strong>Pitta: Show Logs</strong>, with <code>pitta.logLevel</code> set to <code>debug</code>. Every connection attempt, statement and error goes through that channel, credentials redacted.</p><h2 id="it-will-not-connect" tabindex="-1">It will not connect <a class="header-anchor" href="#it-will-not-connect" aria-label="Permalink to &quot;It will not connect&quot;">​</a></h2><h3 id="works-in-psql-mysql-mongosh-not-in-pitta" tabindex="-1">&quot;works in psql / mysql / mongosh, not in Pitta&quot; <a class="header-anchor" href="#works-in-psql-mysql-mongosh-not-in-pitta" aria-label="Permalink to &quot;&quot;works in psql / mysql / mongosh, not in Pitta&quot;&quot;">​</a></h3><p>Nine times in ten this is <a href="./remote">where Pitta is running from</a>. Over Remote-SSH, WSL, a dev container or a Codespace, the connection is made <strong>from the remote machine</strong>, so <code>localhost</code> means the remote&#39;s localhost. Check VS Code&#39;s bottom-left status bar for the window&#39;s remote, then read the <a href="./remote#the-translation-table">translation table</a>.</p><h3 id="timeout-or-connection-refused" tabindex="-1">Timeout, or &quot;connection refused&quot; <a class="header-anchor" href="#timeout-or-connection-refused" aria-label="Permalink to &quot;Timeout, or &quot;connection refused&quot;&quot;">​</a></h3><ul><li>The server is not listening on TCP, or not on that address. PostgreSQL needs <code>listen_addresses</code> to include something other than <code>localhost</code> for a non-loopback client; SQL Server needs the TCP protocol enabled, not just shared memory.</li><li>A firewall or security group is in the way. Managed providers deny by default: the allowlist has to contain the address that is actually connecting, which under Remote-SSH is the remote&#39;s egress address, not your laptop&#39;s.</li><li>The port is right for the wrong thing. Supabase&#39;s pooler, RDS Proxy and PgBouncer all listen on ports that are not the database&#39;s own.</li></ul><h3 id="tls-errors" tabindex="-1">TLS errors <a class="header-anchor" href="#tls-errors" aria-label="Permalink to &quot;TLS errors&quot;">​</a></h3><p><code>self signed certificate in certificate chain</code> or <code>unable to verify the first certificate</code> means verification is on — which is the default and correct — and the CA is not one your system trusts.</p><p>Point the <strong>CA certificate</strong> field at the provider&#39;s bundle rather than turning verification off. Each provider&#39;s file is named in <a href="/pitta-db/recipes/">the recipes</a>.</p><p>Turning verification off is possible, takes a deliberate acknowledgement, and badges the connection <strong>insecure TLS</strong> for as long as it exists. That badge is the point.</p><p>On SQL Server, TLS is two switches rather than one: encryption on, and whether the server&#39;s certificate is trusted. A dev container with a self-signed certificate needs the second one relaxed; a production server should need neither.</p><h3 id="authentication-failed" tabindex="-1">Authentication failed <a class="header-anchor" href="#authentication-failed" aria-label="Permalink to &quot;Authentication failed&quot;">​</a></h3><ul><li>Check which secret Pitta is resolving. A profile using <code>{ &quot;kind&quot;: &quot;env&quot; }</code> reads the environment of the <strong>extension host</strong> — under Remote-SSH that is the remote&#39;s environment, which is a different set of variables from your shell&#39;s.</li><li><code>.pgpass</code> is matched on host, port, database and user, all four. A wildcard line is <code>*</code>.</li><li>PostgreSQL <code>scram-sha-256</code> against a role whose password was set before the server moved to SCRAM will fail until the password is set again.</li><li>MongoDB: the <code>authSource</code> is not always the database you are opening. Atlas users usually authenticate against <code>admin</code>.</li></ul><h3 id="ssh-tunnel-problems" tabindex="-1">SSH tunnel problems <a class="header-anchor" href="#ssh-tunnel-problems" aria-label="Permalink to &quot;SSH tunnel problems&quot;">​</a></h3><ul><li><strong>Host key prompt on a machine that &quot;already knows&quot; the key.</strong> <code>known_hosts</code> is read on the machine Pitta runs on. From a fresh remote or a rebuilt container, it has never seen the bastion.</li><li><strong>Tunnel refused with a message about topology.</strong> Deliberate. A Redis Cluster, a Redis Sentinel set, or a MongoDB SRV / seed-list connection discovers other node addresses after it connects, and a single forwarded port cannot serve addresses that only resolve on the bastion&#39;s side. Half-honouring the tunnel would connect to the seed and then bypass the tunnel for everything else. Use a VPN or a bastion-side proxy.</li><li><strong>Agent authentication fails.</strong> <code>SSH_AUTH_SOCK</code> has to be set in the extension host&#39;s environment. It usually is locally and usually is not inside a container.</li></ul><h2 id="it-connects-then-something-is-wrong" tabindex="-1">It connects, then something is wrong <a class="header-anchor" href="#it-connects-then-something-is-wrong" aria-label="Permalink to &quot;It connects, then something is wrong&quot;">​</a></h2><h3 id="the-tree-is-empty-or-missing-objects" tabindex="-1">The tree is empty, or missing objects <a class="header-anchor" href="#the-tree-is-empty-or-missing-objects" aria-label="Permalink to &quot;The tree is empty, or missing objects&quot;">​</a></h3><ul><li><code>pitta.explorer.showSystemObjects</code> is <code>false</code>, so <code>pg_catalog</code> and <code>information_schema</code> are hidden on purpose.</li><li>The connected role may not have <code>USAGE</code> on the schema. Pitta shows what the catalog will admit to for that role.</li><li>A level with more than <code>pitta.explorer.pageSize</code> objects ends in <strong>Show more</strong> — the rest are not missing, they are the next page.</li><li>Stale after a migration someone else ran? <strong>Refresh</strong> on the node, or set <code>pitta.metadataCacheTtlSeconds</code> lower. DDL that Pitta itself runs invalidates the cache eagerly; DDL run elsewhere cannot.</li></ul><h3 id="editing-is-disabled-on-a-table" tabindex="-1">Editing is disabled on a table <a class="header-anchor" href="#editing-is-disabled-on-a-table" aria-label="Permalink to &quot;Editing is disabled on a table&quot;">​</a></h3><p>The grid says why in that spot. It needs a way to name the row: a primary key, a unique constraint, or an opt-in physical row id (<code>ctid</code>, <code>rowid</code>). A view or a key-less table on an engine with no row-id support has none of the three.</p><h3 id="the-row-count-looks-wrong" tabindex="-1">The row count looks wrong <a class="header-anchor" href="#the-row-count-looks-wrong" aria-label="Permalink to &quot;The row count looks wrong&quot;">​</a></h3><p><code>pitta.explorer.rowCountMode</code> defaults to <code>estimate</code>, which reads the catalog&#39;s estimate and is free but stale between analyses. Set it to <code>exact</code> for a real <code>COUNT(*)</code>, and expect a full scan.</p><h3 id="a-number-lost-its-trailing-digits" tabindex="-1">A number lost its trailing digits <a class="header-anchor" href="#a-number-lost-its-trailing-digits" aria-label="Permalink to &quot;A number lost its trailing digits&quot;">​</a></h3><p>It should not have. <code>numeric</code> and <code>int8</code> are strings and <code>bigint</code> end to end, and an eslint rule fails the build on a <code>Number()</code> in that path. If you can reproduce it, that is a <strong>bug worth reporting</strong> with the column type and the value — it is the class of defect this project cares most about.</p><h3 id="a-null-and-an-empty-cell-look-the-same" tabindex="-1">A <code>NULL</code> and an empty cell look the same <a class="header-anchor" href="#a-null-and-an-empty-cell-look-the-same" aria-label="Permalink to &quot;A `NULL` and an empty cell look the same&quot;">​</a></h3><p>They are not the same and should not render the same: <code>NULL</code> is a styled token. On a schemaless engine a <em>missing</em> field is a third, distinct token. If two of them render alike, report it.</p><h3 id="a-query-is-slow-that-is-fast-elsewhere" tabindex="-1">A query is slow that is fast elsewhere <a class="header-anchor" href="#a-query-is-slow-that-is-fast-elsewhere" aria-label="Permalink to &quot;A query is slow that is fast elsewhere&quot;">​</a></h3><ul><li>Compare with <strong>Explain</strong> rather than with a stopwatch. Pitta reads the plan from the server and flags the node worth looking at.</li><li>The grid asks for one page. A client that takes eight seconds to return everything and a client that takes 200 ms to return the first 500 rows are not measuring the same thing.</li><li><code>pitta.query.streamResults</code> set to <code>false</code> reads up to <code>pitta.maxRowsInMemory</code> before showing anything.</li></ul><h3 id="result-truncated" tabindex="-1">&quot;Result truncated&quot; <a class="header-anchor" href="#result-truncated" aria-label="Permalink to &quot;&quot;Result truncated&quot;&quot;">​</a></h3><p><code>pitta.maxRowsInMemory</code> was reached. That is a memory guard, not a limit on what the server will give you: <strong>export</strong> the result instead, which streams to disk and has no such ceiling.</p><h2 id="statements-and-guards" tabindex="-1">Statements and guards <a class="header-anchor" href="#statements-and-guards" aria-label="Permalink to &quot;Statements and guards&quot;">​</a></h2><h3 id="refused-update-delete-without-where" tabindex="-1">&quot;Refused: UPDATE/DELETE without WHERE&quot; <a class="header-anchor" href="#refused-update-delete-without-where" aria-label="Permalink to &quot;&quot;Refused: UPDATE/DELETE without WHERE&quot;&quot;">​</a></h3><p><code>pitta.query.blockUnqualifiedDml</code> is on, on every connection. Add a <code>WHERE</code>, or turn it off knowingly.</p><h3 id="it-asks-me-to-type-the-connection-name" tabindex="-1">It asks me to type the connection name <a class="header-anchor" href="#it-asks-me-to-type-the-connection-name" aria-label="Permalink to &quot;It asks me to type the connection name&quot;">​</a></h3><p>The connection is tagged <code>prod</code> and the statement is classified destructive. That confirmation is not configurable. If the classification looks wrong, the statement text and the driver&#39;s classification are both in the debug log — a false positive is worth reporting.</p><h3 id="a-redis-command-is-refused-outright" tabindex="-1">A Redis command is refused outright <a class="header-anchor" href="#a-redis-command-is-refused-outright" aria-label="Permalink to &quot;A Redis command is refused outright&quot;">​</a></h3><p><code>KEYS</code> and <code>MONITOR</code> are refused rather than confirmed, because one blocks the server and the other slows it for every client. <code>pitta.redis.allowKeysCommand</code> and <code>pitta.redis.allowMonitor</code> exist; <code>MONITOR</code> stays refused on production regardless.</p><h3 id="an-unfamiliar-command-asks-for-confirmation-on-production" tabindex="-1">An unfamiliar command asks for confirmation on production <a class="header-anchor" href="#an-unfamiliar-command-asks-for-confirmation-on-production" aria-label="Permalink to &quot;An unfamiliar command asks for confirmation on production&quot;">​</a></h3><p>Unknown fails closed. A command Pitta cannot classify on a <code>prod</code> connection is treated as destructive on purpose. If your engine publishes metadata that would classify it, that is a driver improvement worth an issue.</p><h2 id="language-features" tabindex="-1">Language features <a class="header-anchor" href="#language-features" aria-label="Permalink to &quot;Language features&quot;">​</a></h2><h3 id="no-completion-or-diagnostics" tabindex="-1">No completion or diagnostics <a class="header-anchor" href="#no-completion-or-diagnostics" aria-label="Permalink to &quot;No completion or diagnostics&quot;">​</a></h3><ul><li>The file has to be bound to a connection — check the status bar, or add a <code>-- @pitta connection:</code> directive.</li><li><code>pitta.editor.completion</code> and <code>pitta.editor.diagnostics</code> may be off.</li><li>Completion comes from the metadata cache; a schema created seconds ago appears after a refresh.</li><li>On MongoDB, field suggestions come from a <em>sample</em> of documents and say so. A field only present in rare documents may not be sampled.</li></ul><h3 id="the-formatter-did-nothing" tabindex="-1">The formatter did nothing <a class="header-anchor" href="#the-formatter-did-nothing" aria-label="Permalink to &quot;The formatter did nothing&quot;">​</a></h3><p>It runs on files bound to a Pitta connection. Formatting is per language, so a <code>.redis</code> file formats by that driver&#39;s rules, not by SQL&#39;s.</p><h2 id="reporting-a-bug" tabindex="-1">Reporting a bug <a class="header-anchor" href="#reporting-a-bug" aria-label="Permalink to &quot;Reporting a bug&quot;">​</a></h2><p>Include the Pitta version, VS Code version and OS, the engine and server version, whether the window is local or remote, and the debug log around the failure. The <a href="https://github.com/shresthadeepesh/pitta-db/issues/new?template=bug_report.yml" target="_blank" rel="noreferrer">bug template</a> asks for exactly those.</p><p>For anything with a security impact, do <strong>not</strong> open a public issue — see <a href="https://github.com/shresthadeepesh/pitta-db/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>.</p>',48)])])}const g=t(i,[["render",s]]);export{m as __pageData,g as default};
